# Generated by Antigravity CLI 1.4.2 (Gemini 3.8 Flash (High))
"""
Recursively resolves and copies non-system dynamic link libraries (DLLs)
from a MinGW cross-compiler sysroot into a Windows application directory.
"""

import argparse
import os
import re
import shutil
import subprocess
import sys


def parse_dll_dependencies(binary_path, objdump_bin="objdump"):
    """Extracts required DLL names from a PE binary using objdump."""
    try:
        output = subprocess.check_output([objdump_bin, "-p", binary_path], stderr=subprocess.DEVNULL).decode(
            "utf-8", errors="replace"
        )
    except (subprocess.CalledProcessError, FileNotFoundError) as e:
        print(f"Warning: Failed to run {objdump_bin} on {binary_path}: {e}", file=sys.stderr)
        return []

    deps = []
    for line in output.splitlines():
        m = re.match(r"^\s*DLL Name:\s*(\S+)", line, re.IGNORECASE)
        if m:
            deps.append(m.group(1))
    return deps


def main():
    parser = argparse.ArgumentParser(description="Bundle runtime DLLs for MinGW Windows binaries.")
    parser.add_argument("--sysroot-bin", required=True, help="Directory containing MinGW sysroot DLLs")
    parser.add_argument("--dest-dir", required=True, help="Destination directory for copied DLLs")
    parser.add_argument("--objdump", default="objdump", help="Path to objdump utility (default: objdump)")
    parser.add_argument("binaries", nargs="+", help="PE binaries (.exe/.dll) to scan")
    args = parser.parse_args()

    sysroot_bin = os.path.abspath(args.sysroot_bin)
    dest_dir = os.path.abspath(args.dest_dir)
    os.makedirs(dest_dir, exist_ok=True)

    if not os.path.isdir(sysroot_bin):
        print(f"Error: MinGW sysroot bin directory not found: {sysroot_bin}", file=sys.stderr)
        return 1

    # Build case-insensitive index of available sysroot DLLs
    sysroot_dlls = {}
    for entry in os.listdir(sysroot_bin):
        if entry.lower().endswith(".dll"):
            sysroot_dlls[entry.lower()] = entry

    binaries = [os.path.abspath(b) for b in args.binaries if os.path.exists(b)]
    if not binaries:
        print("Error: No existing binaries provided to bundle-dlls.", file=sys.stderr)
        return 1

    copied_dlls = set()
    queue = list(binaries)

    # Breadth-first traversal of non-system DLL dependencies
    while queue:
        curr = queue.pop(0)
        deps = parse_dll_dependencies(curr, objdump_bin=args.objdump)

        for dep in deps:
            dep_key = dep.lower()
            if dep_key in sysroot_dlls and dep_key not in copied_dlls:
                src_filename = sysroot_dlls[dep_key]
                src_path = os.path.join(sysroot_bin, src_filename)
                dst_path = os.path.join(dest_dir, src_filename)

                shutil.copy2(src_path, dst_path)
                os.chmod(dst_path, 0o755)
                copied_dlls.add(dep_key)
                queue.append(dst_path)

    print(f"    Bundled {len(copied_dlls)} runtime DLLs into {dest_dir}:")
    for dll in sorted(copied_dlls):
        print(f"      - {sysroot_dlls[dll]}")

    return 0


if __name__ == "__main__":
    sys.exit(main())
